#include <cstdint>
#include <cstring>
#include <optional>
#include <string>
#include <vector>

struct Line { std::uint64_t address; std::size_t length; std::string text; };

namespace
{
    std::string reg(int number, int bits)
    {
        static const char* const r64[]{ "rax", "rcx", "rdx", "rbx", "rsp", "rbp", "rsi", "rdi" };
        static const char* const r32[]{ "eax", "ecx", "edx", "ebx", "esp", "ebp", "esi", "edi" };
        if (number < 8) return bits == 64 ? r64[number] : r32[number];
        return "r" + std::to_string(number) + (bits == 64 ? "" : "d");
    }

    std::string hex(std::uint64_t v)
    {
        static const char* const HEX{ "0123456789abcdef" };
        std::string out;
        do { out.insert(out.begin(), HEX[v & 0xF]); v >>= 4; } while (v);
        return "0x" + out;
    }

    std::string imm(std::int64_t v) { return v < 0 ? "-" + hex(static_cast<std::uint64_t>(-v)) : hex(static_cast<std::uint64_t>(v)); }

    struct ModRm { int regField; std::string rm; std::string memory; std::size_t length; };

    std::optional<ModRm> modrm(const std::vector<std::uint8_t>& code, std::size_t at, std::uint8_t rex, int bits)
    {
        if (at >= code.size()) return std::nullopt;
        const std::uint8_t m{ code[at] };
        const int mod{ m >> 6 }, rmField{ m & 7 };
        ModRm out{ ((m >> 3) & 7) + ((rex & 4) ? 8 : 0), "", "", 1 };
        if (mod == 3) { out.rm = reg(rmField + ((rex & 1) ? 8 : 0), bits); return out; }
        std::string base, index;
        int scale{ 1 };
        bool rip{ false };
        std::size_t dispSize{ mod == 1 ? 1u : mod == 2 ? 4u : 0u };
        std::size_t i{ at + 1 };
        if (rmField == 4)
        {
            if (i >= code.size()) return std::nullopt;
            const std::uint8_t sib{ code[i++] };
            const int idx{ ((sib >> 3) & 7) + ((rex & 2) ? 8 : 0) }, b{ sib & 7 };
            scale = 1 << (sib >> 6);
            if (idx != 4) index = reg(idx, 64);
            if (b == 5 && mod == 0) dispSize = 4;
            else base = reg(b + ((rex & 1) ? 8 : 0), 64);
        }
        else if (rmField == 5 && mod == 0) { rip = true; dispSize = 4; }
        else base = reg(rmField + ((rex & 1) ? 8 : 0), 64);
        if (i + dispSize > code.size()) return std::nullopt;
        std::int64_t disp{ 0 };
        if (dispSize == 1) disp = static_cast<std::int8_t>(code[i]);
        if (dispSize == 4) { std::int32_t d; std::memcpy(&d, &code[i], 4); disp = d; }
        out.length = i + dispSize - at;
        std::string inside;
        if (rip) inside = "rip" + std::string(disp < 0 ? "" : "+") + imm(disp);
        else
        {
            inside = base;
            if (!index.empty()) inside += (inside.empty() ? "" : "+") + index + "*" + std::to_string(scale);
            if (disp != 0 || inside.empty()) inside += (inside.empty() || disp < 0 ? "" : "+") + imm(disp);
        }
        out.memory = "[" + inside + "]";
        out.rm = std::string(bits == 64 ? "qword ptr " : "dword ptr ") + out.memory;
        return out;
    }

    std::int64_t readSigned(const std::vector<std::uint8_t>& code, std::size_t at, int size)
    {
        if (size == 1) return static_cast<std::int8_t>(code[at]);
        std::int32_t v;
        std::memcpy(&v, &code[at], 4);
        return v;
    }

    std::optional<Line> decode(const std::vector<std::uint8_t>& code, std::size_t start, std::uint64_t base)
    {
        static const char* const cc[]{ "o", "no", "b", "ae", "e", "ne", "be", "a", "s", "ns", "p", "np", "l", "ge", "le", "g" };
        std::size_t i{ start };
        std::uint8_t rex{ 0 };
        if (i < code.size() && code[i] >= 0x40 && code[i] <= 0x4F) rex = code[i++];
        if (i >= code.size()) return std::nullopt;
        const int bits{ (rex & 8) ? 64 : 32 };
        const std::uint8_t op{ code[i++] };
        const std::uint64_t here{ base + start };
        const auto done = [&](std::size_t end, std::string text) -> std::optional<Line> {
            if (end > code.size()) return std::nullopt;
            return Line{ here, end - start, std::move(text) };
        };
        const auto branch = [&](const std::string& name, std::size_t at, int size) -> std::optional<Line> {
            if (at + size > code.size()) return std::nullopt;
            const std::size_t end{ at + size };
            return done(end, name + " " + hex(base + end + static_cast<std::uint64_t>(readSigned(code, at, size))));
        };

        if (op >= 0x50 && op <= 0x57) return done(i, "push " + reg((op - 0x50) + ((rex & 1) ? 8 : 0), 64));
        if (op >= 0x58 && op <= 0x5F) return done(i, "pop " + reg((op - 0x58) + ((rex & 1) ? 8 : 0), 64));
        if (op == 0xC3) return done(i, "ret");
        if (op == 0xCC) return done(i, "int3");
        if (op == 0x90) return done(i, "nop");
        if (op == 0xE8) return branch("call", i, 4);
        if (op == 0xE9) return branch("jmp", i, 4);
        if (op == 0xEB) return branch("jmp", i, 1);
        if (op >= 0x70 && op <= 0x7F) return branch(std::string("j") + cc[op - 0x70], i, 1);
        if (op == 0x0F)
        {
            if (i < code.size() && code[i] >= 0x80 && code[i] <= 0x8F) { const int c{ code[i] - 0x80 }; return branch(std::string("j") + cc[c], i + 1, 4); }
            return std::nullopt;
        }
        if (op >= 0xB8 && op <= 0xBF)
        {
            const std::string r{ reg((op - 0xB8) + ((rex & 1) ? 8 : 0), bits) };
            const std::size_t size{ bits == 64 ? 8u : 4u };
            if (i + size > code.size()) return std::nullopt;
            std::uint64_t v{ 0 };
            for (std::size_t k{ 0 }; k < size; ++k) v |= static_cast<std::uint64_t>(code[i + k]) << (8 * k);
            return done(i + size, "mov " + r + ", " + hex(v));
        }
        const char* rmReg{ nullptr };
        const char* regRm{ nullptr };
        switch (op)
        {
        case 0x01: rmReg = "add"; break;
        case 0x29: rmReg = "sub"; break;
        case 0x31: rmReg = "xor"; break;
        case 0x39: rmReg = "cmp"; break;
        case 0x85: rmReg = "test"; break;
        case 0x89: rmReg = "mov"; break;
        case 0x03: regRm = "add"; break;
        case 0x2B: regRm = "sub"; break;
        case 0x33: regRm = "xor"; break;
        case 0x3B: regRm = "cmp"; break;
        case 0x8B: regRm = "mov"; break;
        default: break;
        }
        if (rmReg || regRm || op == 0x8D)
        {
            const auto m{ modrm(code, i, rex, bits) };
            if (!m) return std::nullopt;
            const std::string r{ reg(m->regField, bits) };
            if (op == 0x8D) return m->memory.empty() ? std::nullopt : done(i + m->length, "lea " + r + ", " + m->memory);
            if (rmReg) return done(i + m->length, std::string(rmReg) + " " + m->rm + ", " + r);
            return done(i + m->length, std::string(regRm) + " " + r + ", " + m->rm);
        }
        if (op == 0x83 || op == 0x81 || op == 0xC7)
        {
            const auto m{ modrm(code, i, rex, bits) };
            if (!m) return std::nullopt;
            const int ext{ m->regField & 7 };
            const char* name{ nullptr };
            if (op == 0xC7) name = ext == 0 ? "mov" : nullptr;
            else name = ext == 0 ? "add" : ext == 4 ? "and" : ext == 5 ? "sub" : ext == 7 ? "cmp" : nullptr;
            if (!name) return std::nullopt;
            const int size{ op == 0x83 ? 1 : 4 };
            const std::size_t at{ i + m->length };
            if (at + size > code.size()) return std::nullopt;
            return done(at + size, std::string(name) + " " + m->rm + ", " + imm(readSigned(code, at, size)));
        }
        return std::nullopt;
    }
}

std::vector<Line> disassemble(const std::vector<std::uint8_t>& code, std::uint64_t base)
{
    std::vector<Line> lines;
    std::size_t at{ 0 };
    while (at < code.size())
    {
        if (const auto line{ decode(code, at, base) }) { lines.push_back(*line); at += line->length; continue; }
        static const char* const HEX{ "0123456789abcdef" };
        lines.push_back({ base + at, 1, std::string("db 0x") + HEX[code[at] >> 4] + HEX[code[at] & 0xF] });
        ++at;
    }
    return lines;
}

