using Bytes = std::vector<std::uint8_t>;
static std::string one(Bytes b, std::uint64_t base = 0x1000) { const auto l{ disassemble(b, base) }; return l.empty() ? "<none>" : l[0].text; }

TEST("stack and simple instructions") {
    CHECK_EQ(one({ 0x55 }), std::string("push rbp"));
    CHECK_EQ(one({ 0x41, 0x5C }), std::string("pop r12"));
    CHECK_EQ(one({ 0xC3 }), std::string("ret"));
    CHECK_EQ(one({ 0xCC }), std::string("int3"));
    CHECK_EQ(one({ 0x48, 0x89, 0xE5 }), std::string("mov rbp, rsp"));
    CHECK_EQ(one({ 0x31, 0xC0 }), std::string("xor eax, eax"));
    CHECK_EQ(one({ 0x85, 0xC0 }), std::string("test eax, eax"));
}
TEST("memory operands") {
    CHECK_EQ(one({ 0x89, 0x7D, 0xFC }), std::string("mov dword ptr [rbp-0x4], edi"));
    CHECK_EQ(one({ 0x8B, 0x45, 0xFC }), std::string("mov eax, dword ptr [rbp-0x4]"));
    CHECK_EQ(one({ 0x48, 0x8B, 0x04, 0xC8 }), std::string("mov rax, qword ptr [rax+rcx*8]"));
    CHECK_EQ(one({ 0x4C, 0x8B, 0x44, 0x24, 0x28 }), std::string("mov r8, qword ptr [rsp+0x28]"));
    CHECK_EQ(one({ 0x48, 0x8D, 0x0D, 0x10, 0x00, 0x00, 0x00 }), std::string("lea rcx, [rip+0x10]"));
}
TEST("immediates") {
    CHECK_EQ(one({ 0x48, 0x83, 0xEC, 0x20 }), std::string("sub rsp, 0x20"));
    CHECK_EQ(one({ 0x48, 0x83, 0xC4, 0x20 }), std::string("add rsp, 0x20"));
    CHECK_EQ(one({ 0x83, 0xF8, 0xFF }), std::string("cmp eax, -0x1"));
    CHECK_EQ(one({ 0x48, 0x81, 0xEC, 0x50, 0x01, 0x00, 0x00 }), std::string("sub rsp, 0x150"));
    CHECK_EQ(one({ 0xC7, 0x45, 0xF8, 0x0A, 0x00, 0x00, 0x00 }), std::string("mov dword ptr [rbp-0x8], 0xa"));
    CHECK_EQ(one({ 0xB8, 0x01, 0x00, 0x00, 0x00 }), std::string("mov eax, 0x1"));
    CHECK_EQ(one({ 0x48, 0xB8, 0xEF, 0xBE, 0xAD, 0xDE, 0, 0, 0, 0 }), std::string("mov rax, 0xdeadbeef"));
    CHECK_EQ(one({ 0x41, 0xB8, 0x03, 0x00, 0x00, 0x00 }), std::string("mov r8d, 0x3"));
}
TEST("branch targets") {
    CHECK_EQ(one({ 0xE8, 0xF5, 0x03, 0x00, 0x00 }, 0x140001000), std::string("call 0x1400013fa"));
    CHECK_EQ(one({ 0x74, 0x0C }, 0x2000), std::string("je 0x200e"));
    CHECK_EQ(one({ 0x7C, 0xF0 }, 0x2000), std::string("jl 0x1ff2"));
    CHECK_EQ(one({ 0x0F, 0x85, 0x00, 0x01, 0x00, 0x00 }, 0x3000), std::string("jne 0x3106"));
    CHECK_EQ(one({ 0xEB, 0xFE }, 0x5000), std::string("jmp 0x5000"));
}
TEST("unknown bytes resynchronise") {
    const auto l{ disassemble({ 0x0F, 0x0B, 0x90, 0x83, 0xC8, 0x01, 0xC3 }, 0) };
    CHECK_EQ(l.size(), 6u);
    if (l.size() != 6) return;
    CHECK_EQ(l[0].text, std::string("db 0x0f"));
    CHECK_EQ(l[1].text, std::string("db 0x0b"));
    CHECK_EQ(l[2].text, std::string("nop"));
    CHECK_EQ(l[3].text, std::string("db 0x83"));
    CHECK_EQ(l[4].text, std::string("db 0xc8"));
    CHECK_EQ(l[5].text, std::string("add ebx, eax"));
    CHECK_EQ(disassemble({ 0xE8, 0x01 }, 0).size(), 2u);
}
TEST("a whole function") {
    const Bytes f{ 0x55, 0x48, 0x89, 0xE5, 0x48, 0x83, 0xEC, 0x10, 0x89, 0x7D, 0xFC, 0x8B, 0x45, 0xFC, 0x01, 0xC0,
                   0x48, 0x83, 0xC4, 0x10, 0x5D, 0xC3 };
    const auto l{ disassemble(f, 0x140001000) };
    CHECK_EQ(l.size(), 9u);
    if (l.size() != 9) return;
    CHECK_EQ(l[7].text, std::string("pop rbp"));
    CHECK_EQ(l[6].address, 0x140001010ull);
    CHECK_EQ(l[5].text, std::string("add eax, eax"));
    std::size_t total{ 0 };
    for (const Line& x : l) total += x.length;
    CHECK_EQ(total, f.size());
}

